-- 0074_labs_writable_pipe_and_vim_sudo_tee: two new typed-command practice
-- labs for the pentest "labs" deck, both requested by the learner directly:
-- Lab 30 breaks the multi-stage pipe `find -writable | cut | grep -v proc |
-- sort -u` into one incremental step per pipeline stage, instead of making
-- the learner type the whole line at once blind. Lab 31 covers the Vim
-- `:w !sudo tee % > /dev/null` trick for saving a file opened without
-- sudo, plus its GTFOBins privesc angle (sudo vim -> shell).

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', c.front, c.payload::jsonb, 'seed'
FROM (VALUES
  ('Lab 30 — Rút gọn danh sách thư mục ghi được (pipe nhiều tầng)', '{"scenario": "Lệnh find / -writable liệt kê hàng nghìn dòng, gần như không đọc nổi. Ghép thêm từng lệnh pipe một, từng bước, để rút gọn dần về danh sách thư mục cấp cao, duy nhất, dễ soi.", "steps": [{"prompt": "Tìm MỌI file/thư mục mà user hiện tại ghi được, quét toàn hệ thống từ /, và bỏ qua lỗi permission denied (xả luồng lỗi vào /dev/null).", "hint": "find / -writable 2>/dev/null", "type": "command", "patterns": ["find\\s+/\\s+-writable\\s+2>\\s*/dev/null"], "explanation": "find / -writable tìm cả file lẫn thư mục (khác -type d chỉ tìm thư mục). 2>/dev/null xả luồng lỗi (stderr, file descriptor 2) để không bị spam hàng nghìn dòng \"Permission denied\" khi quét từ /."}, {"output": "/proc/1234/fd/3\n/proc/1234/task\n/home/alper/notes.txt\n/home/alper/Desktop\n/tmp\n/tmp/.X11-unix\n/var/tmp\n/proc/5678/task\n... (hàng nghìn dòng)", "prompt": "Danh sách quá dài để đọc. Nối thêm 1 lệnh để cắt mỗi dòng path theo dấu / và chỉ lấy field 2 và 3 — rút gọn mỗi dòng về 2 cấp thư mục đầu tiên.", "hint": "find / -writable 2>/dev/null | cut -d \"/\" -f 2,3", "type": "command", "patterns": ["find\\s+/\\s+-writable\\s+2>\\s*/dev/null\\s*\\|\\s*cut\\s+-d\\s+.?/.?\\s+-f\\s+2,3"], "explanation": "cut -d \"/\" -f 2,3 cắt mỗi dòng theo dấu /. Vì path luôn bắt đầu bằng / nên field 1 LUÔN rỗng — field 2 là thư mục cấp 1 (vd home), field 3 là thư mục cấp 2 (vd alper)."}, {"output": "proc/1234\nproc/1234\nhome/alper\nhome/alper\ntmp\ntmp\nvar/tmp\nproc/5678", "prompt": "Rất nhiều dòng bắt đầu bằng proc/... vì /proc luôn báo writable ảo cho mọi process. Loại các dòng đó ra khỏi kết quả.", "hint": "find / -writable 2>/dev/null | cut -d \"/\" -f 2,3 | grep -v proc", "type": "command", "patterns": ["find\\s+/\\s+-writable\\s+2>\\s*/dev/null\\s*\\|\\s*cut\\s+-d\\s+.?/.?\\s+-f\\s+2,3\\s*\\|\\s*grep\\s+-v\\s+proc"], "explanation": "grep -v in ngược lại — chỉ giữ các dòng KHÔNG chứa chuỗi proc (-v = invert). /proc chứa hàng nghìn entry ảo (mỗi process 1 thư mục con), toàn nhiễu, không có giá trị privesc thật."}, {"output": "home/alper\nhome/alper\ntmp\ntmp\nvar/tmp", "prompt": "Kết quả vẫn lặp lại nhiều dòng giống nhau (mỗi file trong cùng 1 thư mục ra 1 dòng trùng). Sắp xếp và loại trùng để có danh sách thư mục duy nhất.", "hint": "find / -writable 2>/dev/null | cut -d \"/\" -f 2,3 | grep -v proc | sort -u", "type": "command", "patterns": ["find\\s+/\\s+-writable\\s+2>\\s*/dev/null\\s*\\|\\s*cut\\s+-d\\s+.?/.?\\s+-f\\s+2,3\\s*\\|\\s*grep\\s+-v\\s+proc\\s*\\|\\s*sort\\s+-u"], "explanation": "sort -u vừa sắp xếp vừa loại dòng trùng (-u = unique) trong 1 bước. Kết quả cuối là danh sách ngắn gọn các thư mục cấp cao ghi được — soi tiếp xem thư mục nào thuộc service/cron chạy quyền cao hơn (root) để tìm hướng privesc."}, {"prompt": "Vì sao bước cut lấy CẢ field 2 và field 3 (không chỉ field 2)?", "type": "choice", "choices": ["Để giữ thêm 1 cấp thư mục con — phân biệt được vd home/alper với home/khac thay vì gộp chung mất thông tin thành chỉ \"home\"", "Vì cut bắt buộc phải truyền ít nhất 2 field, không có lý do kỹ thuật nào khác", "Field 3 là thừa, không ảnh hưởng gì tới kết quả"], "answer": 0, "explanation": "Chỉ lấy field 2 sẽ gộp mọi thứ trong /home lại thành 1 dòng \"home\" duy nhất, mất hẳn thông tin user con nào ghi được — lấy thêm field 3 giữ đủ độ chi tiết cần thiết mà vẫn ngắn gọn hơn nhiều so với path đầy đủ."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"]}'),
  ('Lab 31 — Lưu file cần quyền root ngay trong Vim (:w !sudo tee)', '{"scenario": "Bạn mở /etc/hosts bằng vim để sửa nhưng QUÊN dùng sudo. Sửa xong, gõ :wq thì Vim báo E212: Can''t open file for writing. Đừng thoát ra sửa lại từ đầu — có cách lưu ngay trong Vim.", "steps": [{"output": "E212: Can''t open file for writing", "prompt": "Đang ở trong Vim (chế độ Normal), gõ lệnh để GHI nội dung buffer hiện tại ra chính file đang mở (ký hiệu %) thông qua sudo, mà không cần thoát Vim.", "hint": ":w !sudo tee % > /dev/null", "type": "command", "patterns": [":w\\s+!sudo\\s+tee\\s+%\\s*>\\s*/dev/null"], "explanation": ":w !<lệnh> trong Vim nghĩa là PIPE toàn bộ nội dung buffer ra 1 lệnh shell, thay vì tự ghi ra file như :w bình thường. % là ký hiệu đại diện tên file đang mở. tee % đọc nội dung từ stdin rồi GHI LẠI vào chính file đó — và vì tee được gọi qua sudo nên có quyền ghi dù user hiện tại không có. > /dev/null chặn tee in lại nội dung ra màn hình (tee mặc định vừa ghi file vừa in ra stdout, gây rối giao diện Vim)."}, {"prompt": "Sau khi chạy lệnh trên thành công, Vim vẫn hiện dấu [+] trên statusline (coi buffer là chưa lưu) dù file trên đĩa đã đúng. Vì sao, và nên làm gì tiếp?", "type": "choice", "choices": ["tee ghi thẳng ra đĩa, bỏ qua cơ chế :w nội bộ của Vim nên Vim không tự biết buffer đã khớp file — gõ :q! để thoát không lưu lại là đủ (an toàn vì file đã đúng), không cần lưu thêm lần nữa", "Lệnh chắc chắn đã lỗi, file chưa được ghi, cần làm lại từ đầu", "Phải khởi động lại máy thì Vim mới nhận ra file đã lưu"], "answer": 0, "explanation": "tee ghi trực tiếp ra filesystem, hoàn toàn bỏ qua cơ chế theo dõi thay đổi nội bộ của Vim — nên Vim vẫn coi buffer \"dirty\" dù nội dung trên đĩa đã đúng. :q! (thoát không lưu) là đủ vì file đã được ghi đúng bởi tee rồi."}, {"prompt": "Đây cũng là 1 kỹ thuật PRIVESC trên GTFOBins khi sudo -l cho phép chạy vim/vi KHÔNG giới hạn file cụ thể nào. Gõ lệnh (trong terminal, không phải trong Vim) để mở /etc/shadow bằng sudo qua vim.", "hint": "sudo vim /etc/shadow", "type": "command", "patterns": ["sudo\\s+vim\\s+/etc/shadow", "sudo\\s+vi\\s+/etc/shadow"], "explanation": "Nếu sudo -l liệt kê (ALL) /usr/bin/vim (hoặc vi) không giới hạn file cụ thể, mở BẤT KỲ file nào — kể cả /etc/shadow, /etc/sudoers — bằng sudo vim là Vim đã chạy sẵn dưới quyền root, không cần tới mẹo :w !sudo tee nữa vì cả tiến trình Vim đã là root."}, {"prompt": "Khi sudo vim đã chạy với quyền root, cách nhanh nhất để có SHELL root ngay trong Vim (theo GTFOBins) là gì?", "type": "choice", "choices": [":!sudo sh hoặc chỉ :!/bin/sh — vì Vim đang chạy quyền root nên tiến trình shell con cũng kế thừa đúng quyền đó", "Phải thoát Vim trước rồi gõ sudo -i như bình thường", "Không thể lấy được shell từ bên trong Vim"], "answer": 0, "explanation": ":! chạy 1 lệnh shell từ bên trong Vim, tiến trình con kế thừa đúng quyền của Vim đang chạy — nếu Vim chạy dưới sudo thì shell con đó cũng là shell root ngay lập tức. Đây là entry chuẩn của vim trên GTFOBins (mục Sudo)."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1", "OSCP"]}')
) AS c(front, payload)
JOIN decks d ON d.slug = 'labs'
  AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'pentest')
ON CONFLICT DO NOTHING;
